use vstd::prelude::*;

verus! {

/// Mathematical absolute value on integers.
spec fn iabs(x: int) -> int {
    if x >= 0 { x } else { -x }
}

fn solve(w: i8, a: i8, b: i8) -> (res: i8)
    ensures
        // Result matches the intended math over unbounded integers.
        res as int
            == (if iabs(a as int - b as int) <= w as int {
                    0
                } else {
                    iabs(a as int - b as int) - w as int
                }),
        // In particular, the result is never negative.
        res as int >= 0,
        // And it always fits in i8 (stronger than needed, but true).
        res as int <= i8::MAX as int,
{
    // Work in i16 to avoid any issues with i8 overflow when taking differences.
    let w = w as i16;
    let a = a as i16;
    let b = b as i16;

    let diff = (a - b).abs();
    let ans = if diff <= w { 0 } else { diff - w };

    // Help Verus connect the i16 computation with the int spec.
    assert(diff as int == iabs(a as int - b as int));

    // Show the cast to i8 is safe: ans is within [0, 127].
    assert(ans >= 0);
    assert(ans <= i8::MAX as i16);

    ans as i8
}

} // verus!

